<?php
namespace App\Http\Controllers;
use App\Models\StudyBuddyLaunchChecklistItem;use App\Models\StudyBuddyMiniAppPlatform;use App\Models\StudyBuddyPlatformSetting;use App\Models\StudyBuddyPointTransaction;use Illuminate\Http\Request;use Illuminate\Validation\Rule;
class StudyBuddyFinalAdminController extends Controller{public function index(){return view('admin.studybuddy.final-platform.index',['settings'=>StudyBuddyPlatformSetting::orderBy('group_name')->orderBy('sort_order')->get(),'apps'=>StudyBuddyMiniAppPlatform::ordered()->get(),'checks'=>StudyBuddyLaunchChecklistItem::orderBy('sort_order')->get(),'recentPoints'=>StudyBuddyPointTransaction::latest()->take(12)->get()]);} public function updateSettings(Request $r){$d=$r->validate(['settings'=>['array'],'settings.*'=>['nullable','string','max:5000']]);foreach(($d['settings']??[]) as $k=>$v){StudyBuddyPlatformSetting::where('setting_key',$k)->update(['setting_value'=>$v]);}return back()->with('status','Platform settings saved.');} public function updateApp(Request $r,StudyBuddyMiniAppPlatform $app){$d=$r->validate(['name'=>['required','string','max:160'],'category'=>['nullable','string','max:120'],'tagline'=>['nullable','string','max:240'],'description'=>['nullable','string','max:4000'],'status'=>['required',Rule::in(['concept','planned','beta','live','paused'])],'icon'=>['nullable','string','max:24'],'web_play_url'=>['nullable','string','max:500','regex:/^(https?:\/\/|\/)[^\s]*$/i'],'ios_url'=>['nullable','string','max:500','regex:/^https?:\/\/[^\s]+$/i'],'android_url'=>['nullable','string','max:500','regex:/^https?:\/\/[^\s]+$/i'],'windows_url'=>['nullable','string','max:500','regex:/^(https?:\/\/|\/)[^\s]*$/i'],'mac_url'=>['nullable','string','max:500','regex:/^(https?:\/\/|\/)[^\s]*$/i'],'points_reward'=>['required','integer','min:0','max:500'],'estimated_minutes'=>['required','integer','min:1','max:240'],'is_web_enabled'=>['nullable','boolean'],'is_download_enabled'=>['nullable','boolean'],'is_featured'=>['nullable','boolean'],'is_active'=>['nullable','boolean']]);foreach(['is_web_enabled','is_download_enabled','is_featured','is_active'] as $b){$d[$b]=$r->boolean($b);} $app->update($d);return back()->with('status',"{$app->name} updated.");} public function updateChecklist(Request $r,StudyBuddyLaunchChecklistItem $item){$item->update($r->validate(['status'=>['required',Rule::in(['todo','doing','done','blocked'])],'priority'=>['required',Rule::in(['low','medium','high','critical'])],'description'=>['nullable','string','max:4000'],'owner_label'=>['nullable','string','max:160']]));return back()->with('status','Launch checklist updated.');} public function quickAward(Request $r){$d=$r->validate(['user_id'=>['required','integer','exists:users,id'],'title'=>['required','string','max:180'],'points'=>['required','integer','min:-500','max:500']]);StudyBuddyPointTransaction::create(['user_id'=>$d['user_id'],'source_type'=>'admin_adjustment','source_slug'=>'admin-final-cockpit','title'=>$d['title'],'points'=>$d['points'],'status'=>$d['points']>=0?'earned':'adjusted','meta'=>['admin_id'=>$r->user()?->id]]);return back()->with('status','Points adjustment saved.');}}
